<?php
declare(strict_types=1);
final class PatternEngine {
 static function signal(string $id,array $p,array $s,array $config,int $expiry,string $rules):array {
  $now=$s['observed_at'];$close=intdiv($now,900)*900;$direction=$p['direction']==='SHORT'?'BEARISH':$p['direction'];$scope=MarketScope::current();$uid=PatternConfig::opportunity($scope['symbol'],$id,$direction,$close,$scope['exchange'],$scope['account_id']);
  return array_replace($p,['id'=>$uid,'exchange'=>$scope['exchange'],'account_id'=>$scope['account_id'],'symbol'=>$scope['symbol'],'strategy_id'=>$id,'rules_version'=>$rules,'direction'=>$direction,'timeframe'=>'15m','confirmation_candle_close'=>$close,'candle_close'=>$close,'candle_utc'=>gmdate('Y-m-d\TH:i:s\Z',$close),'detected_at'=>$now,'sent_at'=>null,'reference_price'=>$p['reference_price'],'pattern_status'=>'PATTERN_CONFIRMED','execution_status'=>'NOT_EVALUATED','execution_limitations'=>array_merge(['ORDER_BOOK_FRESHNESS_NOT_CHECKED','FEES_DEPTH_CAPITAL_NOT_CHECKED','CHART_LEVELS_NOT_EXECUTABLE_PRICES'],$direction==='BEARISH'?['SPOT_BEARISH_IS_NOT_EXECUTABLE_SHORT']:[]),'expires_at'=>$close+$expiry,'config_snapshot'=>$config,'data_received_at'=>$s['frame_received_at']['15m']??$s['received_at'],'publication_delay_seconds'=>($s['first_seen_at']['15m']??$s['received_at'])-$close,'level_kind'=>'CHART_REFERENCE_ONLY']);
 }
 static function step(array &$state,array $s,array $config,array $breakConfig):array {
  $now=$s['observed_at']??null;$result=['methods'=>[],'signals'=>[]];if(!is_int($now)||$now<1)throw new RuntimeException('Observation time missing');
  foreach($config['methods'] as $id=>$p){$method=$state[$id]??[];$scope=MarketScope::current();$card=['exchange'=>$scope['exchange'],'symbol'=>$scope['symbol'],'account_id'=>$scope['account_id'],'strategy_id'=>$id,'name'=>PatternConfig::name($id),'enabled'=>$config['enabled']&&$p['enabled'],'data_status'=>'NOT_EVALUATED','pattern_status'=>'DISABLED','execution_status'=>'NOT_EVALUATED','reason'=>'روش خاموش است.','last_signal'=>$method['last_signal']??null];
   if(!$card['enabled']){$result['methods'][$id]=$card;continue;}
   try{
    if(($s['provider']??null)!==$scope['exchange']||($s['symbol']??null)!==$scope['symbol'])throw new RuntimeException('UNAVAILABLE: market provenance');
    $counts=$id===PatternConfig::MEAN?['15m'=>PatternConfig::meanCount($p)]:ScannerConfig::counts($breakConfig);$card['required_candles']=$counts;$card['data_health']=PatternData::health($s,$counts);$card['last_successful_check']=$method['last_successful_check']??null;$bars=[];foreach($counts as $tf=>$count)$bars[$tf]=PatternData::window($s,$tf,$count);$close=end($bars['15m'])['time']+900;$card['data_status']='SUFFICIENT';$card['required_candles']=$counts;
    $fingerprints=[];$revised=[];foreach($bars as $tf=>$items)foreach($items as $bar){$key=$tf.':'.$bar['time'];$hash=hash('sha256',json_encode($bar,JSON_THROW_ON_ERROR));if(isset($method['_fingerprints'][$key])&&$method['_fingerprints'][$key]!==$hash)$revised[]=$key;$fingerprints[$key]=$hash;}
    // A provider revision invalidates the setup, not the entire rolling window forever.
    // Keep emitted signals immutable and wait for a new candle before starting again.
    if($revised){$method['_fingerprints']=$fingerprints;unset($method['pattern'],$method['last_evaluation']);$method['last_close']=$close;$method['reason']='دادهٔ تاریخی صرافی اصلاح شد؛ ستاپ قبلی کنار گذاشته شد و ارزیابی از کندل بعدی ادامه می‌یابد.';$method['data_revision']=['detected_at'=>$now,'count'=>($method['data_revision']['count']??0)+1,'candles'=>$revised,'resume_after_close'=>$close];$card['data_revision']=$method['data_revision'];throw new RuntimeException('UNAVAILABLE: CONFLICTING_CLOSED_CANDLE '.$revised[0]);}
    $method['_fingerprints']=$fingerprints;if(isset($method['data_revision']))$card['data_revision']=$method['data_revision'];
    PatternData::fresh($s,$config,$close);$card['last_successful_check']=$method['last_successful_check']=$now;
    if($close<=($method['last_close']??0)){$card=array_replace($card,$method['last_evaluation']??[]);$card['pattern_status']=($method['last_signal']['confirmation_candle_close']??null)===$close&&$close>($method['data_revision']['resume_after_close']??0)?'PATTERN_CONFIRMED':'WAITING_PATTERN';$card['reason']=$method['reason']??'منتظر کندل بسته‌شدهٔ تازه.';$state[$id]=$method;$result['methods'][$id]=$card;continue;}
    if($id===PatternConfig::MEAN){$evaluation=MeanReversion::evaluate($bars['15m'],$p);$method['last_close']=$close;$confirmed=$evaluation['pattern_status']==='PATTERN_CONFIRMED';$expiry=$p['expiry_seconds'];$rules=MeanReversion::RULES;}
    else{$keys=['ema_fast','ema_slow','atr_period','level_lookback','level_touches','touch_separation','level_tolerance_atr','break_buffer_atr','retest_tolerance_atr','confirm_buffer_atr','volume_period','break_volume_ratio','confirm_volume_ratio','setup_bars','entry_expiry_seconds','entry_band_atr','structure_buffer_atr','stop_atr','max_stop_atr','tp1_r','tp2_r'];$fingerprint=hash('sha256',json_encode(array_intersect_key($breakConfig,array_flip($keys)),JSON_THROW_ON_ERROR));$pattern=($method['rules_fingerprint']??$fingerprint)===$fingerprint?($method['pattern']??[]):[];$method['rules_fingerprint']=$fingerprint;unset($pattern['candidate']);$r=BreakRetestScanner::evaluate($pattern,$bars,$breakConfig,$now);$method['pattern']=$pattern;$method['last_close']=$close;$confirmed=isset($r['candidate']);$evaluation=$confirmed?$r['candidate']:['pattern_status'=>'WAITING_PATTERN','reason'=>$r['reason'],'conditions'=>$r['conditions'],'setup_status'=>$r['status']];$expiry=$breakConfig['entry_expiry_seconds'];$rules=ScannerConfig::RULES_VERSION;unset($method['pattern']['candidate']);}
    $method['last_evaluation']=$evaluation;$card=array_replace($card,$evaluation);$card['strategy_id']=$id;$card['execution_status']='NOT_EVALUATED';
    if($confirmed){$card['pattern_status']='PATTERN_CONFIRMED';$signal=self::signal($id,$evaluation,$s,$id===PatternConfig::MEAN?$p:$breakConfig,$expiry,$rules);$signal['reference_target']??=$signal['targets'][0]??null;$signal['suggested_invalidation']??=$signal['invalidation_price']??null;$signal['direction']=$evaluation['direction']==='SHORT'?'BEARISH':$evaluation['direction'];if($now>=$signal['expires_at']){$card['pattern_status']='EXPIRED';$card['reason']='مهلت بررسی الگو پیش از کشف پایان یافته است.';}else{$method['last_signal']=$signal;$card['last_signal']=$signal;$result['signals'][]=$signal;}}
    $method['reason']=$card['reason'];$state[$id]=$method;
   }catch(Throwable $e){$card['pattern_status']='UNAVAILABLE';$card['reason']=$e->getMessage();$freshnessError=str_contains($e->getMessage(),'STALE_RECEIPT')||str_contains($e->getMessage(),'LATE_CANDLE_PUBLICATION');if(!$freshnessError)$card['data_status']='INSUFFICIENT';
    // Explain the last closed candle without advancing state or emitting a stale signal.
    if($freshnessError&&$card['data_status']==='SUFFICIENT'){try{if($id===PatternConfig::MEAN)$diagnostic=MeanReversion::evaluate($bars['15m'],$p);else{$copy=$method['pattern']??[];unset($copy['candidate']);$diagnostic=BreakRetestScanner::evaluate($copy,$bars,$breakConfig,$now);}foreach(['conditions','conditions_by_direction','indicators'] as $field)if(isset($diagnostic[$field]))$card[$field]=$diagnostic[$field];$card['diagnostics_only']=true;$card['diagnostic_candle_close']=$close;}catch(Throwable $ignored){}}
   }
   $state[$id]=$method;$result['methods'][$id]=$card;
  }return $result;
 }
 static function message(array $p):string {$direction=$p['direction']==='LONG'?'جهت خرید':'الگوی نزولی';return MarketScope::label($p['exchange']??'wallex').' / '.$p['symbol'].' — الگوی '.PatternConfig::name($p['strategy_id']).'، '.$direction.'، در کندل بسته‌شدهٔ ۱۵دقیقه UTC '.$p['candle_utc'].' تأیید شد. قیمت مرجع: '.$p['reference_price'].' USDT. شرایط اجرای معامله بررسی نشده است.'.($p['direction']==='BEARISH'?' این الگوی نموداری، امکان بازکردن شورت در بازار نقدی را تأیید نمی‌کند.':'');}
}
